      "java_oop": {
        "title": "Java OOP",
        "summary": "Prinsip dasar Object-Oriented Programming: Enkapsulasi, Abstraksi, Pewarisan (Inheritance), dan Polimorfisme.",
        "content": "<p class=\"lead\">Prinsip dasar Object-Oriented Programming: Enkapsulasi, Abstraksi, Pewarisan (Inheritance), dan Polimorfisme.</p>\n<div class=\"card bg-light border-0 p-3 mb-4 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-brands fa-java text-danger me-2\"></i>Konsep Kunci Java OOP:</h6>\n    <p class=\"small mb-0\" style=\"line-height: 1.8;\">\n        Pelajari arsitektur sintaks Java di bawah, perhatikan aturan kompilasi JVM yang ketat (Strongly-Typed), dan uji secara langsung di Code Lab Skillance Academy.\n    </p>\n</div>",
        "example_title": "Contoh Kode Java: Java OOP",
